## Implementation

The existing dollar-denominated `unitPrice` is retained as an input boundary; pricing arithmetic and all returned money use integer cents.

For deterministic pricing, pass `today` as the **store-local `YYYY-MM-DD` date** when using a recognized promo. The module deliberately does not guess the store timezone or read the system clock.

### `pricing.ts`

```ts
export type Category = 'grocery' | 'household' | 'alcohol';

export interface LineItem {
  sku: string;
  name: string;
  unitPrice: number; // Input boundary: dollars, at most two decimal places
  qty: number;
  category: Category;
}

export interface Cart {
  items: LineItem[];
  memberTier: 'none' | 'plus';
}

export type PromoCode = 'FRESH10' | 'SAVE5' | 'HOME15';
export type PromoFailure =
  | 'unknown'
  | 'expired'
  | 'below_minimum'
  | 'no_eligible_items';

type PromoDefinition = {
  scope: 'non_alcohol' | 'household';
  minimumCents: number;
  validThrough: string;
} & (
  | { type: 'percent'; basisPoints: number }
  | { type: 'fixed'; amountCents: number }
);

export const PROMOS = {
  FRESH10: {
    type: 'percent',
    basisPoints: 1000,
    scope: 'non_alcohol',
    minimumCents: 4000,
    validThrough: '2025-12-31',
  },
  SAVE5: {
    type: 'fixed',
    amountCents: 500,
    scope: 'non_alcohol',
    minimumCents: 2500,
    validThrough: '2025-06-30',
  },
  HOME15: {
    type: 'percent',
    basisPoints: 1500,
    scope: 'household',
    minimumCents: 0,
    validThrough: '2025-12-31',
  },
} as const satisfies Readonly<Record<PromoCode, PromoDefinition>>;

export type PromoResult =
  | { status: 'not_requested' }
  | { status: 'applied'; code: PromoCode }
  | { status: 'rejected'; code: string; reason: PromoFailure };

export interface Amounts {
  subtotalCents: number;
  memberDiscountCents: number;
  promoDiscountCents: number;
  netCents: number; // After both discounts, before tax
  taxableCents: number;
  taxCents: number;
  totalCents: number;
}

export interface PricedLine extends Amounts {
  sku: string;
  name: string;
  qty: number;
  category: Category;
  unitPriceCents: number;
}

export interface CartPrice {
  lines: PricedLine[];
  totals: Amounts;
  promo: PromoResult;
}

function nonnegativeInteger(value: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${label} must be a nonnegative safe integer`);
  }
  return value;
}

function safeNumber(value: bigint): number {
  return nonnegativeInteger(Number(value), 'Money');
}

function sum(values: readonly number[]): number {
  return safeNumber(values.reduce((total, value) => total + BigInt(value), 0n));
}

// Avoid binary floating-point multiplication when converting the input boundary.
function dollarsToCents(value: number): number {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError('unitPrice must be nonnegative and finite');
  }

  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(String(value));
  if (!match) {
    throw new RangeError('unitPrice must have at most two decimal places');
  }

  return safeNumber(
    BigInt(match[1]) * 100n +
      BigInt((match[2] ?? '').padEnd(2, '0')),
  );
}

// Exact half-up rounding for a nonnegative rational amount.
function roundRatio(numerator: bigint, denominator: bigint): number {
  return safeNumber(
    (2n * numerator + denominator) / (2n * denominator),
  );
}

function basisPointAmount(cents: number, basisPoints: number): number {
  return roundRatio(BigInt(cents) * BigInt(basisPoints), 10_000n);
}

/**
 * Proportional allocation:
 * 1. Cap the requested discount at the available amount.
 * 2. Round each proportional share half-up.
 * 3. Correct the remainder on the largest line(s), preserving 0 <= share <= line.
 * Ties are resolved by original line order.
 */
export function allocateFixedDiscount(
  weights: readonly number[],
  requestedCents: number,
): number[] {
  weights.forEach(weight => nonnegativeInteger(weight, 'Weight'));
  nonnegativeInteger(requestedCents, 'Discount');

  const available = sum(weights);
  const target = Math.min(requestedCents, available);

  if (target === 0) return weights.map(() => 0);

  const shares = weights.map(weight =>
    roundRatio(BigInt(target) * BigInt(weight), BigInt(available)),
  );

  let remainder = target - sum(shares);
  const order = weights
    .map((_, index) => index)
    .sort((a, b) => weights[b] - weights[a] || a - b);

  for (const index of order) {
    if (remainder === 0) break;

    if (remainder > 0) {
      const adjustment = Math.min(
        remainder,
        weights[index] - shares[index],
      );
      shares[index] += adjustment;
      remainder -= adjustment;
    } else {
      const adjustment = Math.min(-remainder, shares[index]);
      shares[index] -= adjustment;
      remainder += adjustment;
    }
  }

  return shares;
}

function requireStoreDate(today: string | undefined): string {
  if (!today || !/^\d{4}-\d{2}-\d{2}$/.test(today)) {
    throw new RangeError('Provide the store-local date as YYYY-MM-DD');
  }

  const parsed = new Date(`${today}T00:00:00.000Z`);
  if (
    !Number.isFinite(parsed.getTime()) ||
    parsed.toISOString().slice(0, 10) !== today
  ) {
    throw new RangeError('Invalid store-local date');
  }

  return today;
}

function isPromoCode(code: string): code is PromoCode {
  return Object.hasOwn(PROMOS, code);
}

function eligible(category: Category, definition: PromoDefinition): boolean {
  return (
    category !== 'alcohol' &&
    (definition.scope === 'non_alcohol' || category === 'household')
  );
}

export function priceCart(
  cart: Cart,
  promoCode?: string,
  today?: string,
): CartPrice {
  const baseLines = cart.items.map(item => {
    nonnegativeInteger(item.qty, 'qty');

    const unitPriceCents = dollarsToCents(item.unitPrice);
    const subtotalCents = safeNumber(
      BigInt(unitPriceCents) * BigInt(item.qty),
    );
    const memberDiscountCents =
      cart.memberTier === 'plus' && item.category !== 'alcohol'
        ? basisPointAmount(subtotalCents, 500)
        : 0;

    return {
      sku: item.sku,
      name: item.name,
      qty: item.qty,
      category: item.category,
      unitPriceCents,
      subtotalCents,
      memberDiscountCents,
      remainingCents: subtotalCents - memberDiscountCents,
    };
  });

  // Also enforce the safe-integer limit for the entire cart.
  sum(baseLines.map(line => line.subtotalCents));

  let promo: PromoResult = { status: 'not_requested' };
  let promoDiscounts = baseLines.map(() => 0);

  if (promoCode !== undefined) {
    const code = promoCode.trim().toUpperCase();

    if (!isPromoCode(code)) {
      promo = { status: 'rejected', code, reason: 'unknown' };
    } else {
      const definition: PromoDefinition = PROMOS[code];
      const date = requireStoreDate(today);
      const matches = baseLines.map(line =>
        eligible(line.category, definition),
      );
      const eligibleSubtotal = sum(
        baseLines.map((line, index) =>
          matches[index] ? line.subtotalCents : 0,
        ),
      );
      const weights = baseLines.map((line, index) =>
        matches[index] ? line.remainingCents : 0,
      );

      let reason: PromoFailure | undefined;

      if (date > definition.validThrough) {
        reason = 'expired';
      } else if (sum(weights) === 0) {
        reason = 'no_eligible_items';
      } else if (eligibleSubtotal < definition.minimumCents) {
        reason = 'below_minimum';
      }

      if (reason !== undefined) {
        promo = { status: 'rejected', code, reason };
      } else {
        promo = { status: 'applied', code };
        promoDiscounts =
          definition.type === 'fixed'
            ? allocateFixedDiscount(weights, definition.amountCents)
            : weights.map(weight =>
                basisPointAmount(weight, definition.basisPoints),
              );
      }
    }
  }

  const lines: PricedLine[] = baseLines.map((line, index) => {
    const { remainingCents, ...details } = line;
    const promoDiscountCents = promoDiscounts[index];
    const netCents = remainingCents - promoDiscountCents;
    const taxableCents = line.category === 'grocery' ? 0 : netCents;
    const taxCents = basisPointAmount(taxableCents, 825);

    return {
      ...details,
      promoDiscountCents,
      netCents,
      taxableCents,
      taxCents,
      totalCents: sum([netCents, taxCents]),
    };
  });

  const total = (key: keyof Amounts) => sum(lines.map(line => line[key]));

  return {
    lines,
    totals: {
      subtotalCents: total('subtotalCents'),
      memberDiscountCents: total('memberDiscountCents'),
      promoDiscountCents: total('promoDiscountCents'),
      netCents: total('netCents'),
      taxableCents: total('taxableCents'),
      taxCents: total('taxCents'),
      totalCents: total('totalCents'),
    },
    promo,
  };
}
```

