describe('allocateFixedDiscount', () => {
  it('caps the discount at the eligible amount', () => {
    expect(allocateFixedDiscount([100, 200, 0], 500))
      .toEqual([100, 200, 0]);
    expect(allocateFixedDiscount([], 500)).toEqual([]);
  });

  it('puts positive rounding remainder on the largest line', () => {
    expect(allocateFixedDiscount([100, 101, 100], 1))
      .toEqual([0, 1, 0]);
