  it('preserves totals and bounds across small allocation edge cases', () => {
    for (let a = 0; a <= 5; a++) {
      for (let b = 0; b <= 5; b++) {
        for (let discount = 0; discount <= 15; discount++) {
          const weights = [a, b, 2];
          const shares = allocateFixedDiscount(weights, discount);

          expect(shares.reduce((s, value) => s + value, 0))
            .toBe(Math.min(discount, a + b + 2));

          shares.forEach((share, index) => {
            expect(Number.isInteger(share)).toBe(true);
            expect(share).toBeGreaterThanOrEqual(0);
